package com.bank.concurrent;

import java.math.BigDecimal;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;
import java.util.logging.*;

public class ThreadSafeImmutableDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws InterruptedException {
        int threads = 8, perThread = 1000;
        ExecutorService pool = Executors.newFixedThreadPool(threads);

        // Immutable Money shared freely; we accumulate via an atomic reference swap.
        AtomicReference<Money> total = new AtomicReference<>(new Money(BigDecimal.ZERO));
        // Mutable, UNSYNCHRONIZED balance -> will lose updates under concurrency.
        UnsafeBalance unsafe = new UnsafeBalance();

        CountDownLatch latch = new CountDownLatch(threads);
        for (int t = 0; t < threads; t++) {
            pool.submit(() -> {
                for (int i = 0; i < perThread; i++) {
                    // Lock-free correct accumulation of immutable values.
                    total.updateAndGet(cur -> cur.add(new Money(BigDecimal.ONE)));
                    // Racy mutable write -> lost updates.
                    unsafe.add(1);
                }
                latch.countDown();
            });
        }
        latch.await();
        pool.shutdown();

        int expected = threads * perThread;
        log.info(() -> "Expected total = " + expected);
        log.info(() -> "Immutable Money total = " + total.get() + " (CORRECT, no locks)");
        log.warning(() -> "Unsafe mutable total = " + unsafe.get() + " (likely < expected, lost updates)");
    }
}

