// Immutable value class: inherently thread-safe, shareable with NO synchronization.
final class Money {
    private final BigDecimal amount; // final -> safely published, never changes
    Money(BigDecimal amount) { this.amount = amount; }
    Money add(Money other) { return new Money(amount.add(other.amount)); } // returns NEW
    public String toString() { return "Rs." + amount; }
}

// ─── Would be UnsafeBalance.java in a real project ───
// Mutable: concurrent writes race; would NEED synchronization to be correct.
class UnsafeBalance {
    private int value = 0;
    void add(int n) { value = value + n; } // read-modify-write race
    int get() { return value; }
}
